import torch

def run(self, assert_msg, dep_token):
    if self.numel() != 1:
        raise RuntimeError("Boolean value of Tensor with more than one value is ambiguous")
    if not torch.is_nonzero(self.reshape(())):
        raise RuntimeError(assert_msg)
    return dep_token.clone()

def gen_inputs(ctx, device):
    self_dtype = getattr(torch, ctx["self__dtype"])
    dep_shape = ctx["dep_token__shape"]
    dep_dtype = getattr(torch, ctx["dep_token__dtype"])
    self = torch.ones(1, dtype=self_dtype, device=device)
    dep = torch.randn(dep_shape, dtype=dep_dtype, device=device)
    return {"self": self, "assert_msg": "Assertion is failed", "dep_token": dep}
